<?php
namespace App\Http\Controllers;
use App\Models\{ChannelMessage,ConnectorConfig,Lead,OutreachEvent};
use App\Services\{ChannelOutbox,CountryPolicy};
use Illuminate\Http\Request;
use Illuminate\Support\{Str,Facades\Cache};
class ChannelController {
 public function index(){return view('channels',['messages'=>ChannelMessage::with('lead')->latest()->paginate(20),'gateways'=>ConnectorConfig::where('purpose','outreach')->where('enabled',true)->get()]);}
 public function create(Request $r){$d=$r->validate(['lead_id'=>'required|integer|exists:leads,id','connector_id'=>'required|uuid|exists:connector_configs,id','recipient'=>['required','string','max:254','not_regex:/[\r\n]/'],'body'=>'required|string|max:12000','permission'=>'accepted','parent_id'=>'nullable|uuid']);$lead=Lead::findOrFail($d['lead_id']);abort_if(app(\App\Services\OutboxService::class)->closed($lead),422,'Lead closed or country review required.');$c=ConnectorConfig::findOrFail($d['connector_id']);abort_unless($c->enabled&&$c->purpose==='outreach',422);if(preg_match('/^\+?(?:91|92)[0-9\s()-]{6,}$/',$d['recipient']))abort(422,'Destination country is excluded.');$parent=null;if(!empty($d['parent_id'])){$parent=ChannelMessage::whereKey($d['parent_id'])->where('lead_id',$lead->id)->where('connector_id',$c->id)->where('status','sent')->firstOrFail();abort_unless($parent->sequence<(app(\App\Services\ProspectingProfile::class)->data()['max_followups']??2),422);abort_if(ChannelMessage::where('parent_id',$parent->id)->exists(),422,'Follow-up already exists.');}
  ChannelMessage::create(['id'=>(string)Str::uuid(),'lead_id'=>$lead->id,'connector_id'=>$c->id,'recipient'=>$d['recipient'],'body'=>$d['body'],'permission_at'=>now(),'parent_id'=>$parent?->id,'sequence'=>$parent?$parent->sequence+1:0]);return back()->with('notice','Channel message saved as draft. An administrator must approve its exact destination and content.');}
 public function approve(Request $r,ChannelMessage $message,ChannelOutbox $outbox){$d=$r->validate(['approval'=>'accepted','digest'=>'required|string|size:64']);try{$outbox->approve($message,$d['digest']);return back()->with('notice','Exact channel message approved.');}catch(\Throwable $e){return back()->withErrors(['approval'=>'Review the latest message, gateway settings, country and contact permission before approving.']);}}
 public function cancel(ChannelMessage $message){$lock=Cache::lock('channel-send:'.$message->id,30);abort_unless($lock->get(),409);try{abort_unless(in_array($message->fresh()->status,['draft','approved'],true),409);$message->update(['status'=>'cancelled','approval_hash'=>null]);}finally{$lock->release();}return back()->with('notice','Channel message cancelled.');}
 public function edit(Request $r,ChannelMessage $message){$d=$r->validate(['recipient'=>['required','string','max:254','not_regex:/[\r\n]/'],'body'=>'required|string|max:12000','permission'=>'accepted']);if(preg_match('/^\+?(?:91|92)[0-9\s()-]{6,}$/',$d['recipient']))abort(422,'Destination country is excluded.');$lock=Cache::lock('channel-send:'.$message->id,30);abort_unless($lock->get(),409);try{abort_unless(in_array($message->fresh()->status,['draft','approved'],true),409);$message->update(['recipient'=>$d['recipient'],'body'=>$d['body'],'permission_at'=>now(),'status'=>'draft','approval_hash'=>null,'approved_at'=>null]);}finally{$lock->release();}return back()->with('notice','Edits saved; a fresh exact-message approval is required.');}
 public function resolve(Request $r,ChannelMessage $message){$d=$r->validate(['checked_provider'=>'accepted','resolution'=>'required|in:confirmed_sent,confirmed_not_sent']);$lock=Cache::lock('channel-send:'.$message->id,30);abort_unless($lock->get(),409);try{abort_unless($message->fresh()->status==='delivery_unknown',409);$sent=$d['resolution']==='confirmed_sent';$message->update(['status'=>$sent?'sent':'draft','sent_at'=>$sent?now():null,'approved_at'=>null,'approval_hash'=>null,'error_code'=>$sent?'MANUALLY_CONFIRMED_SENT':'MANUALLY_CONFIRMED_NOT_SENT','followup_due_at'=>$sent?now()->addDays(3):null]);OutreachEvent::create(['lead_id'=>$message->lead_id,'event'=>'channel_'.$d['resolution']]);}finally{$lock->release();}return back()->with('notice','Provider result recorded. A resend needs fresh approval.');}
 public function receipt(Request $r){$d=$r->validate(['message_id'=>'required|uuid','sender'=>'required|string|max:254','outcome'=>'required|in:reply,unsubscribe,bounce','provider_event_id'=>'nullable|string|max:190','snippet'=>'nullable|string|max:1200']);$m=ChannelMessage::find($d['message_id']);if(!$m||$m->recipient!==$d['sender']||(!in_array($m->status,['sent','delivery_unknown'],true)&&!in_array($m->error_code,['MANUALLY_CONFIRMED_NOT_SENT','MANUALLY_CONFIRMED_SENT'],true)))return response()->json(['matched'=>false]);
  \Illuminate\Support\Facades\DB::transaction(function()use($m,$d){$lead=Lead::whereKey($m->lead_id)->lockForUpdate()->firstOrFail();$key=hash('sha256','channel|'.($d['provider_event_id']??json_encode($d)));$intent=\App\Services\InboxProcessor::intent($d['snippet']??'',$d['outcome']);$event=\App\Models\InboxEvent::firstOrCreate(['event_key'=>$key],['lead_id'=>$lead->id,'outbound_message_id'=>$m->id,'provider'=>'channel','provider_message_id'=>$d['provider_event_id']??$key,'sender'=>$d['sender'],'subject'=>'Channel reply','intent'=>$intent,'classification_method'=>'keyword_rules_reviewable','excerpt'=>$d['snippet']??null]);if(!$event->wasRecentlyCreated)return;app(\App\Services\OutboxService::class)->outcome($lead,$intent==='unsubscribe'?'unsubscribe':($intent==='bounce'?'bounce':'reply'),'authenticated_channel_callback');$lead->refresh();$lead->reply_intent=$intent;$lead->save();});return response()->json(['matched'=>true]);}
}
